{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Apply parameter-free RMS normalization with epsilon 1e-6 to input item embeddings across all four datasets, preserving zero padding and unchanged output embeddings. This may stabilize GRU gate inputs for sparse items. The predictor writer already imports the updated model class, ensuring identical inference normalization without checkpoint changes.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        emb = emb * torch.rsqrt(emb.square().mean(dim=-1, keepdim=True) + 1e-6)\n        emb = emb.masked_fill(seq.eq(0).unsqueeze(-1), 0.0)\n        return self.dropout(emb)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.input_embeddings(seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.input_embeddings(seq)"
        }
      ]
    }
  ],
  "change_summary": "Normalize input embeddings before dropout in training and inference. Preserve embedding dimensions, output embeddings, GRU topology, aggregation, scoring, loss, optimizer, and per-dataset checkpoint routing."
}
